draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 - 40 + 20 * Math.sin(t), H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 + 40 + 20 * Math.sin(t + Math.PI), H/2 + 20);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t + Math.PI), H/2 + 90);
  ctx.stroke();

  // mouth
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 40, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
